    /** Usable text width inside the scroll area (padding already accounted for). */
    int textWrapWidth() {
        int w = contentWidth();     // get the current width of the content area from the scroll pane's viewport, which allows us to determine how much horizontal space is available for the text elements (title, body text, key fact) to wrap within, ensuring that they adjust their widths to fit within the visible area while maintaining good readability and visual appeal across different screen sizes and content variations, contributing to a polished and user-friendly design for the learning module panel that effectively organizes the educational material while maintaining good readability and visual appeal across different screen sizes and content variations
        return Math.max(200, w - 52);       // return the usable text width by subtracting the horizontal padding (14px on each side plus an additional 24px for internal spacing) from the total content width, while ensuring a minimum width of 200 pixels to maintain readability even on smaller screens, which helps to ensure that the text elements have enough space to wrap properly and remain visually appealing across different screen sizes and content variations, contributing to a polished and user-friendly design for the learning module panel that effectively organizes the educational material while maintaining good readability and visual appeal across different screen sizes and content variations
    }

    int contentWidth() {
        if (contentScroll != null) {
            int w = contentScroll.getViewport().getWidth();     // get the current width of the viewport of the scroll pane, which represents the visible area for the content and allows us to determine how much horizontal space is available for the text elements (title, body text, key fact) to wrap within, ensuring that they adjust their widths to fit within the visible area while maintaining good readability and visual appeal across different screen sizes and content variations, contributing to a polished and user-friendly design for the learning module panel that effectively organizes the educational material while maintaining good readability and visual appeal across different screen sizes and content variations
            if (w > 0) return w;        // if the width is greater than 0, return it as the content width to be used for calculating the text wrap width, which helps to ensure that the text elements have enough space to wrap properly and remain visually appealing across different screen sizes and content variations, contributing to a polished and user-friendly design for the learning module panel that effectively organizes the educational material while maintaining good readability and visual appeal across different screen sizes and content variations
        }
        int w = getWidth();     // if the scroll pane is not initialized or the viewport width is not available, fall back to using the overall width of the panel as the content width, which allows us to still calculate a reasonable text wrap width for the text elements (title, body text, key fact) to wrap within, ensuring that they adjust their widths to fit within the visible area while maintaining good readability and visual appeal across different screen sizes and content variations, contributing to a polished and user-friendly design for the learning module panel that effectively organizes the educational material while maintaining good readability and visual appeal across different screen sizes and content variations
        return w > 0 ? w : 448;     // if the panel width is greater than 0, return it; otherwise, return a default width of 448 pixels to ensure that the text elements have enough space to wrap properly and remain visually appealing even when the panel size is not yet determined, contributing to a polished and user-friendly design for the learning module panel that effectively organizes the educational material while maintaining good readability and visual appeal across different screen sizes and content variations
    }

    static String htmlWrap(String text, int widthPx, String fontCss) {
        return "<html><body style='width:" + widthPx + "px;" + fontCss + "'>"
                + htmlEscape(text) + "</body></html>";      // wrap the given text in HTML tags with a specified width and font CSS styles, which allows us to control the layout and appearance of the text within the JLabel by enabling line wrapping at the specified width and applying consistent font styling, contributing to a polished and user-friendly design for the learning module panel that effectively organizes the educational material while maintaining good readability and visual appeal across different screen sizes and content variations
    }

    static String htmlEscape(String s) {
        if (s == null) return "";
        return s.replace("&", "&amp;")
              .replace("<", "&lt;")
              .replace(">", "&gt;");        // escape special HTML characters in the given string to prevent them from being interpreted as HTML tags or entities, which helps to ensure that the text is displayed correctly and safely within the JLabel when using HTML formatting, contributing to a polished and user-friendly design for the learning module panel that effectively organizes the educational material while maintaining good readability and visual appeal across different screen sizes and content variations
    }

    /** Width for text inside the key-fact box (accounts for its border and padding). */
    int factWrapWidth() {
        return Math.max(180, textWrapWidth() - 30);     // calculate the usable text width for the key fact text area by taking the overall text wrap width and subtracting additional space for the key fact panel's border and padding, while ensuring a minimum width of 180 pixels to maintain readability even on smaller screens, which helps to ensure that the key fact text has enough space to wrap properly and remain visually appealing across different screen sizes and content variations, contributing to a polished and user-friendly design for the learning module panel that effectively highlights important information while maintaining good readability and visual appeal across different screen sizes and content variations
    }

    void syncTextAreaWidth(JTextArea area, int wrap) {
        syncTextAreaWidth(area, wrap, 0);       // synchronize the width of the given JTextArea to fit within the specified wrap width, which helps to maintain a consistent and visually appealing layout for the text elements (title, body text, key fact) by ensuring that they adjust their widths to fit within the visible area while maintaining good readability and visual appeal across different screen sizes and content variations, contributing to a polished and user-friendly design for the learning module panel that effectively organizes the educational material while maintaining good readability and visual appeal across different screen sizes and content variations
    }

    void syncTextAreaWidth(JTextArea area, int wrap, int extraHeight) {
        area.setSize(new Dimension(wrap, Short.MAX_VALUE));     // set the size of the JTextArea to the specified wrap width and a very large height to allow it to calculate the preferred height based on the wrapped text, which helps to ensure that the text elements (title, body text, key fact) adjust their heights appropriately based on their content while maintaining the specified width for wrapping, contributing to a polished and user-friendly design for the learning module panel that effectively organizes the educational material while maintaining good readability and visual appeal across different screen sizes and content variations
        Dimension pref = area.getPreferredSize();       // get the preferred size of the JTextArea after setting its width, which allows us to determine the appropriate height for the text area based on the wrapped content, ensuring that it adjusts its height to fit the text while maintaining the specified width for wrapping, contributing to a polished and user-friendly design for the learning module panel that effectively organizes the educational material while maintaining good readability and visual appeal across different screen sizes and content variations
        int h = Math.max(pref.height + extraHeight, pref.height);       // calculate the height for the JTextArea by taking the preferred height and adding any extra height if specified, while ensuring that it is at least as tall as the preferred height to accommodate the wrapped text, which helps to maintain a visually appealing layout for the text elements (title, body text, key fact) by ensuring that they have enough vertical space to display their content without being cut off while maintaining the specified width for wrapping, contributing to a polished and user-friendly design for the learning module panel that effectively organizes the educational material while maintaining good readability and visual appeal across different screen sizes and content variations
        area.setPreferredSize(new Dimension(wrap, h));      // set the preferred size of the JTextArea to the specified wrap width and the calculated height, which helps to ensure that the text elements (title, body text, key fact) adjust their sizes appropriately based on their content while maintaining the specified width for wrapping, contributing to a polished and user-friendly design for the learning module panel that effectively organizes the educational material while maintaining good readability and visual appeal across different screen sizes and content variations
        area.setMaximumSize(new Dimension(wrap, Integer.MAX_VALUE));        // set the maximum size of the JTextArea to the specified wrap width and a very large height to allow it to expand vertically as needed based on its content while maintaining the specified width for wrapping, which helps to ensure that the text elements (title, body text, key fact) can grow in height to accommodate their content without being constrained while maintaining good readability and visual appeal across different screen sizes and content variations, contributing to a polished and user-friendly design for the learning module panel that effectively organizes the educational material while maintaining good readability and visual appeal across different screen sizes and content variations
    }

    void syncBodyAreaFixedHeight(int wrap) {
        txtBody.setSize(new Dimension(wrap, BODY_BOX_H));       // set the size of the body text area to the specified wrap width and a fixed height defined by BODY_BOX_H, which helps to maintain a consistent height for the body text area across all content pages regardless of the amount of text, ensuring that the layout remains visually balanced and appealing while allowing the text to wrap within the specified width, contributing to a polished and user-friendly design for the learning module panel that effectively organizes the educational material while maintaining good readability and visual appeal across different screen sizes and content variations
        txtBody.setPreferredSize(new Dimension(wrap, BODY_BOX_H));      // set the preferred size of the body text area to the specified wrap width and the fixed height defined by BODY_BOX_H to ensure that it maintains a consistent height across all content pages, which helps to create a visually balanced layout for the body text while allowing it to wrap within the specified width, contributing to a polished and user-friendly design for the learning module panel that effectively organizes the educational material while maintaining good readability and visual appeal across different screen sizes and content variations
        txtBody.setMinimumSize(new Dimension(wrap, BODY_BOX_H));        // set the minimum size of the body text area to the specified wrap width and the fixed height defined by BODY_BOX_H to ensure that it does not shrink below this size, which helps to maintain a consistent and visually appealing layout for the body text across all content pages while allowing it to wrap within the specified width, contributing to a polished and user-friendly design for the learning module panel that effectively organizes the educational material while maintaining good readability and visual appeal across different screen sizes and content variations
        txtBody.setMaximumSize(new Dimension(wrap, BODY_BOX_H));        // set the maximum size of the body text area to the specified wrap width and the fixed height defined by BODY_BOX_H to ensure that it does not grow beyond this size, which helps to maintain a consistent and visually appealing layout for the body text across all content pages while allowing it to wrap within the specified width, contributing to a polished and user-friendly design for the learning module panel that effectively organizes the educational material while maintaining good readability and visual appeal across different screen sizes and content variations
    }

    /** Keep title, body, and key fact within the visible panel width. */
    void syncContentWidths() {
        int wrap = textWrapWidth();     // calculate the usable text wrap width based on the current content width, which allows us to ensure that the title, body text, and key fact adjust their widths to fit within the visible area of the scroll pane while maintaining good readability and visual appeal across different screen sizes and content variations, contributing to a polished and user-friendly design for the learning module panel that effectively organizes the educational material while maintaining good readability and visual appeal across different screen sizes and content variations
        if (wrap <= 0) return;      // if the calculated wrap width is not positive, return early to avoid setting invalid sizes for the text areas, which helps to prevent potential layout issues and maintain a visually appealing design for the learning module panel even when the panel size is not yet determined or is too small, contributing to a polished and user-friendly design for the learning module panel that effectively organizes the educational material while maintaining good readability and visual appeal across different screen sizes and content variations

        syncTextAreaWidth(txtTitle, wrap);      // synchronize the width of the title text area to fit within the calculated wrap width, which helps to maintain a consistent and visually appealing layout for the title by ensuring that it adjusts its width to fit within the visible area of the scroll pane while maintaining good readability and visual appeal across different screen sizes and content variations, contributing to a polished and user-friendly design for the learning module panel that effectively organizes the educational material while maintaining good readability and visual appeal across different screen sizes and content variations
        // Keep lesson body box height consistent across all pages.
        syncBodyAreaFixedHeight(wrap);      // synchronize the body text area to have a fixed height defined by BODY_BOX_H while adjusting its width to fit within the calculated wrap width, which helps to maintain a consistent and visually appealing layout for the body text across all content pages by ensuring that it has the same height regardless of the amount of text while allowing it to wrap within the specified width, contributing to a polished and user-friendly design for the learning module panel that effectively organizes the educational material while maintaining good readability and visual appeal across different screen sizes and content variations
        if (txtFact != null && pnlFact.isVisible()) {
            syncTextAreaWidth(txtFact, factWrapWidth());        // if the key fact text area is initialized and the key fact panel is visible, synchronize the width of the key fact text area to fit within the calculated fact wrap width, which helps to maintain a consistent and visually appealing layout for the key fact by ensuring that it adjusts its width to fit within the visible area of the scroll pane while maintaining good readability and visual appeal across different screen sizes and content variations, contributing to a polished and user-friendly design for the learning module panel that effectively highlights important information while maintaining good readability and visual appeal across different screen sizes and content variations
        }

        if (contentInner != null) {
            contentInner.revalidate();      // if the inner content panel is initialized, revalidate it to ensure that the layout is updated based on the new sizes of the text areas, which helps to maintain a visually appealing and well-organized layout for the content pages by ensuring that all components adjust their positions and sizes appropriately after the text areas have been resized, contributing to a polished and user-friendly design for the learning module panel that effectively organizes the educational material while maintaining good readability and visual appeal across different screen sizes and content variations
        }
    }

